{
  "up": "Select molecule_chembl_id AS compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism From molecule_dictionary MD Join activities ACT ON MD.molregno = ACT.molregno Join assays AS ON ACT.assay_id = AS.assay_id Join target_dictionary TD ON AS.tid = TD.tid Join compound_structures CS ON MD.molregno = CS.molregno Join compound_records CR ON ACT.record_id = CR.record_id Join docs D ON CR.doc_id = D.doc_id Join pubmeds P ON D.pubmed_id = P.pubmed_id Join doi_lookup DOI ON D.doi = DOI.doi WHERE MD.chembl_id = 'CHEMBL3650' AND AS.assay_type = 'B' AND AS.assay_organism = 'Homo sapiens' AND ACT.bao_endpoint = 'BAO_0000006' AND ACT.standard_type = 'IC50' AND ACT.standard_relation = '=' AND ACT.standard_value IS NOT NULL AND ACT.standard_units = 'nM' AND P.pubmed_id IS NOT NULL OR DOI.doi IS NOT NULL AND CS.canonical_smiles IS NOT NULL"
}
